const L=id=>D.lessons.find(l=>l.id===id), A=id=>D.assets.find(a=>a.id===id), M=id=>D.modules.find(m=>m.id===id), P=id=>D.projects.find(p=>p.id===id);
const defaults={version:1,name:'Darshak',theme:'violet',mode:'light',motion:'auto',scale:1,rate:1,path:'beginner',hours:6,complete:{},quizzes:{},notes:{},checks:{},drafts:{},lastLesson:'engineering-method',custom:[]};
