for(const k of ['complete','quizzes','notes','checks','drafts'])if(!S[k]||typeof S[k]!=='object'||Array.isArray(S[k]))S[k]={};
if(!Array.isArray(S.custom))S.custom=[];
let storageWarned=false;
const save=()=>{try{localStorage.setItem('kinetic-studio-v1',JSON.stringify(S));}catch{if(!storageWarned){storageWarned=true;toast('Storage is unavailable or full. Export your progress before closing.');}}};
let cleanup=[],currentScene=null,currentLab=null,codeWorker=null,codeTimer=null,editorDraft=null,routeToken=0,route=[],autoSlide=null,guidedProject=null;
const reduced=()=>S.motion==='reduced'||S.motion==='auto'&&matchMedia('(prefers-reduced-motion: reduce)').matches;
function appearance(){document.documentElement.dataset.theme=S.theme;document.documentElement.dataset.mode=S.mode;document.documentElement.style.setProperty('--scale',Math.max(.85,Math.min(1.25,Number(S.scale)||1)));document.body.classList.toggle('reduce-motion',reduced());}
function toast(t){let el=$('#toast');if(!el){el=document.createElement('div');el.id='toast';el.className='toast';el.setAttribute('role','status');document.body.append(el);}el.textContent=t;el.hidden=false;clearTimeout(el.timer);el.timer=setTimeout(()=>el.hidden=true,5000);}
function download(name,content,type='application/json'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function dispose(){cleanup.forEach(f=>{try{f();}catch{}});cleanup=[];currentScene?.destroy();currentScene=null;currentLab?.destroy();currentLab=null;stopCode(false);clearInterval(autoSlide);autoSlide=null;window.speechSynthesis?.cancel();}
function header(){const nav=[['home','Overview'],['learn','Learn'],['build','Build'],['sandbox','Simulate'],['code','Code'],['atlas','Explore'],['library','Library']];$('#header').innerHTML=`<a class="brand" href="#/home" aria-label="Kinetic home"><span class="brand-icon">${icon('chip')}</span><span>kinetic<em>Robotics studio</em></span></a><nav class="nav" aria-label="Main navigation">${nav.map(([id,label])=>`<a href="#/${id}" data-nav="${id}">${label}</a>`).join('')}</nav><div class="top-actions"><button class="icon-btn" data-action="search" aria-label="Search lessons, projects and components" title="Search ( / )">${icon('search')}</button><button class="icon-btn" data-action="theme-mode" aria-label="Toggle light and dark appearance" title="Toggle appearance">${icon(S.mode==='dark'?'sun':'moon')}</button><a class="icon-btn" href="#/settings" aria-label="Customize workspace" title="Customize">${icon('settings')}</a><span class="avatar" title="Your local learner profile">${esc((S.name||'Learner').slice(0,2).toUpperCase())}</span></div>`;}
const footer=()=>`<footer class="footer"><span>Made for curious minds. Built around evidence.<br><span class="muted">Local-first learning studio &middot; Teaching models, not safety-certified systems.</span></span><div class="row wrap"><a href="#/lesson/sources">Sources &amp; boundaries</a><a href="#/settings">Your workspace</a><button class="btn quiet small" data-action="export-progress">Export progress ${icon('download')}</button></div></footer>`;
const crumb=(label,parent)=>`<div class="crumb"><a href="#/home">Workspace</a><span>/</span>${parent?`<a href="#/${parent[0]}">${esc(parent[1])}</a><span>/</span>`:''}<span>${esc(label)}</span></div>`;
const heading=(title,desc,actions='')=>`<div class="page-heading"><div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div><div class="actions">${actions}</div></div>`;
const reviewed=()=>D.lessons.filter(l=>S.complete[l.id]).length;
const percent=ids=>Math.round(ids.filter(id=>S.complete[id]).length/Math.max(ids.length,1)*100);
const simArt=id=>({circuit:'circuit',pid:'pid',rover:'rover',arm:'arm',path:'path',rl:'rl'})[id]||'chip';
function moduleCard(m){return `<a class="module-card" href="#/module/${m.id}"><div class="module-art ${m.color}"><span class="module-no">MODULE ${m.id}</span>${Visuals.art(simArt(m.sim))}<span class="module-count">${m.lessons.length} lessons</span></div><div class="module-body"><h3>${esc(m.title)}</h3><p>${esc(m.subtitle)}</p><div class="module-meta"><span>${percent(m.lessons)}% reviewed</span>${icon('arrow')}</div><div class="progress-bar"><i style="width:${percent(m.lessons)}%"></i></div></div></a>`;}
function projectCard(p){return `<a class="project-card" href="#/project/${p.id}/0"><div class="project-visual ${M(p.module)?.color||''}"><span class="project-num">BUILD ${String(p.number).padStart(2,'0')}</span><span class="badge">${esc(p.level)}</span>${Visuals.art(simArt(p.sim))}</div><div class="project-copy"><h3>${esc(p.title)}</h3><p>${esc(p.intro)}</p><div class="row between"><span class="muted small">${esc(p.type)} &middot; 5 guided stages</span>${icon('arrow')}</div></div></a>`;}
function robotMarkup(){return `<div class="hero-lab"><canvas class="scene-canvas" tabindex="0" aria-label="Interactive conceptual desk robot. Drag to rotate. Use arrow keys to rotate; E to explode."></canvas><div class="scene-top"><span class="badge">YOUR FIRST DESK COMPANION</span><span class="badge">Interactive 3D</span></div><div class="scene-tooltip" hidden></div><div class="scene-bottom"><div class="segmented"><button class="active" data-scene="shell">Whole</button><button data-scene="inside">Inside</button><button data-scene="exploded">Exploded</button></div><span class="scene-label">Drag to explore</span></div></div>`;}
function mountRobot(){const cv=$('.scene-canvas');if(!cv)return;currentScene=new Visuals.RobotScene(cv,{motion:!reduced(),onPart:part=>{const el=$('.scene-tooltip');if(!el)return;el.hidden=!part;if(part)el.innerHTML=`<strong>${esc(part.name)}</strong>${esc(part.text)}`;}});$$('[data-scene]').forEach(b=>b.addEventListener('click',()=>{currentScene.setMode(b.dataset.scene);$$('[data-scene]').forEach(q=>q.classList.toggle('active',q===b));}));}
function home(){return StudioUI.home();}
function learn(){return StudioUI.learn();}
function scope(){dialog('The bigger picture',`<p class="muted">An eight-semester-inspired scope map. Use these outcomes to plan sustained practice, not as a claim of accredited equivalence.</p><div class="semester-grid">${D.semesters.map((s,i)=>`<div class="semester"><span class="semester-no">0${i+1}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.topics)}</p><p class="evidence"><strong>Evidence to produce:</strong> ${esc(s.evidence)}</p><div class="actions">${s.modules.map(id=>`<a class="btn small" href="#/module/${id}" data-close>Module ${id}</a>`).join('')}</div></div></div>`).join('')}</div><p class="quality-note">Scope cross-checks: Carnegie Mellon's robotics curriculum, MIT Circuits and Underactuated Robotics, and Northwestern Modern Robotics. Open source syllabi and lectures are in the Library. Plan mathematics and hardware practice beyond this introductory content.</p>`);}
function moduleView(id,tab){return StudioUI.moduleView(id,tab);}
function lessonView(id,tab='understand'){const l=L(id)||L('engineering-method'),m=M(l.module)||D.modules[0];S.lastLesson=l.id;save();const tabs=[['understand','Understand'],['practice','Try it'],['check','Check yourself'],['notes','My notes']];let body='';if(tab==='practice'){body=`<div class="lab-challenge"><div><span class="caps">FROM READING TO DOING</span><h3>Make one prediction before you run.</h3><p>Write the expected outcome, change one variable, and compare measured evidence with your prediction.</p></div><a class="btn primary" href="#/sandbox/${l.sim||m.sim}">Open live lab ${icon('lab')}</a></div>${l.steps.length?`<h3>Your practical sequence</h3><div class="checklist">${l.steps.map((s,i)=>`<label><input type="checkbox" data-check="${l.id}-${i}" ${S.checks[l.id+'-'+i]?'checked':''}><span>${esc(s)}</span></label>`).join('')}</div>`:'<p>Open the related lab, change one parameter, and export the result. Write a short explanation of the model assumptions. These are learning exercises, not hardware qualification.</p>'}${l.kind==='project'?`<a class="btn" href="#/project/${l.id}/0">Open five-stage build journey ${icon('arrow')}</a>`:''}`;}else if(tab==='check'){body=l.quizzes.length?l.quizzes.map((q,i)=>quizHTML(q,l.id,i)).join(''):`<h3>Explain, demonstrate, diagnose.</h3><p>Use the questions in the lesson as an oral engineering review. A defensible answer states assumptions, units, boundary conditions and failure behavior.</p><div class="quiz-card"><h3>Teach this concept in three sentences.</h3><p>What problem does it solve? What evidence shows it works? What could invalidate your conclusion?</p><textarea data-note="teach-${l.id}" rows="6" style="width:100%" placeholder="My explanation...">${esc(S.notes['teach-'+l.id]||'')}</textarea><p class="note muted">Saved locally as you type. This reflection is not automatically graded.</p></div>`;}else if(tab==='notes'){body=`<h3>Your engineering notebook</h3><p class="muted">Capture what you observed, not only what you intended.</p><textarea data-note="${l.id}" rows="17" style="width:100%" placeholder="Question / hypothesis\nSetup and versions\nPrediction\nMeasurements and units\nWhat failed?\nWhat would I change?">${esc(S.notes[l.id]||'')}</textarea><div class="actions" style="margin-top:14px"><button class="btn" data-action="export-note" data-id="${l.id}">Export note ${icon('download')}</button></div><p class="note muted">Stored on this browser only. Export your notebook to back it up.</p>`;}else body=l.body;
 return `${crumb(l.title,['module/'+m.id,'Module '+m.id])}<div class="lesson-layout"><aside class="lesson-nav"><a class="caps" href="#/module/${m.id}">MODULE ${m.id}</a><h3>${esc(m.title)}</h3>${m.lessons.filter(id=>L(id)).map((id,i)=>`<a class="${id===l.id?'active':''}" href="#/lesson/${id}"><span>${S.complete[id]?'\u2713':String(i+1).padStart(2,'0')}</span>${esc(L(id).title)}</a>`).join('')}<div class="quality-note">Learn the idea. Try it. Explain it.<br><a href="#/atlas">Explore real components</a></div></aside><section class="reader"><div class="reader-heading"><div class="row between wrap"><span class="kicker">${l.kind==='project'?'PROJECT LESSON':'LEARNING STUDIO'} / ${m.id}</span><div class="actions"><button class="btn quiet small" data-action="narrate">${icon('volume')} Read aloud</button><button class="btn quiet small" data-action="focus">${icon('fullscreen')} Focus</button></div></div><h1>${esc(l.title)}</h1><p>${esc(l.intro)}</p></div><nav class="reader-tabs" aria-label="Lesson tabs">${tabs.map(([key,label])=>`<a class="${tab===key?'active':''}" href="#/lesson/${l.id}/${key}">${label}</a>`).join('')}</nav><article class="article" id="lesson-body">${body}</article><div class="lesson-bottom"><button class="btn ${S.complete[l.id]?'':'primary'}" data-action="complete" data-id="${l.id}">${icon('check')} ${S.complete[l.id]?'Reviewed - mark unread':'Mark reviewed'}</button><span class="small muted">Reading progress, not certification.</span><a class="btn quiet small" href="#/lesson/${nextLesson(l.id)}">Next lesson ${icon('arrow')}</a></div></section><aside class="notes-panel"><span class="caps muted">YOUR EXPERIMENT</span><h4 style="margin-top:13px">The useful question</h4><p class="small muted">What would change the result, and how would you know?</p><a class="btn small" href="#/sandbox/${l.sim||m.sim}">Try the model ${icon('lab')}</a><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><h4>Scratchpad</h4><textarea data-note="scratch-${l.id}" rows="8" style="width:100%;font-size:12px" placeholder="A prediction, a measurement, an unfamiliar word...">${esc(S.notes['scratch-'+l.id]||'')}</textarea><p class="note muted">Saved automatically on this device.</p>${l.refs.length?`<h4 style="margin-top:24px">Go to the source</h4>${l.refs.slice(0,3).map(r=>`<p class="small">${link(r.url,esc(r.label))}</p>`).join('')}`:''}</aside></div>`;
}
function nextLesson(id){const order=D.modules.flatMap(m=>m.lessons).filter(id=>L(id));const i=order.indexOf(id);return order[Math.min(order.length-1,i+1)]||'engineering-method';}
function quizHTML(q,id,i){const stored=S.quizzes[id+'-'+i];return `<section class="quiz-card" data-quiz="${id}:${i}"><span class="caps muted">THINK BEFORE REVEALING</span><h3 style="margin-top:10px">${esc(q.question)}</h3><div class="quiz-options">${q.options.map((s,n)=>`<button data-answer="${n}" class="${stored===n?(n===q.correct?'correct':'wrong'):''}"><span class="answer-label">${String.fromCharCode(65+n)}</span>${esc(s)}</button>`).join('')}</div><div class="quiz-result" ${stored===undefined?'hidden':''}>${stored===undefined?'':`<strong>${stored===q.correct?'Correct.':'Not quite.'}</strong> ${esc(q.explanation)}`}</div></section>`;}
function photo(id,{compact=false,hotspots=true}={}){const a=A(id);if(!a)return '';return `<figure class="photo" data-photo="${esc(id)}"><div class="image-box"><img src="${esc(a.url)}" alt="${esc(a.title)} - ${esc(a.owner)}" loading="lazy" decoding="async" referrerpolicy="no-referrer"><div class="loading-message"><span class="tile-icon">${icon(a.category==='Software'?'grid':'photo')}</span><strong>${esc(a.title)}</strong><p>Loading the credited source image...</p>${link(a.sourceUrl,'Open original source','btn small')}</div>${hotspots?a.markers.map(([x,y,label,text],i)=>`<button class="hotspot ${x>65?'right':''}" style="left:${x}%;top:${y}%" data-hotspot="${id}:${i}" aria-label="${esc(label)}: ${esc(text)}"><span class="hot-label">${esc(label)}</span></button>`).join(''):''}<button class="zoom-photo icon-btn" data-zoom="${id}" title="Enlarge image" aria-label="Enlarge ${esc(a.title)}">${icon('fullscreen')}</button></div><figcaption><span class="badge">${esc(a.kind)}</span><strong>${esc(a.title)}</strong>${compact?'':`${esc(a.note||'Inspect the physical markings and match the exact revision before connecting anything.')}<br>`}<span>${esc(a.owner)} &middot; </span>${link(a.sourceUrl,'Source &amp; context')}</figcaption></figure>`;}
function hydrateMedia(){const token=routeToken;$$('.asset-slot').forEach(el=>el.outerHTML=photo(el.dataset.asset));$$('.image-box img').forEach(img=>{const parent=img.parentElement;const onload=()=>{if(routeToken!==token)return;parent.classList.add('loaded');const msg=$('.loading-message',parent);if(msg)msg.hidden=true;};const onerror=()=>{if(routeToken!==token)return;parent.classList.remove('loaded');parent.classList.add('failed');const msg=$('.loading-message p',parent);if(msg)msg.textContent='This source image needs internet access and may be blocked by its host. The source link still takes you to the documented component.';};img.addEventListener('load',onload);img.addEventListener('error',onerror);if(img.complete)img.naturalWidth?onload():onerror();});$$('.thumb img').forEach(img=>{const ok=()=>img.parentElement.classList.add('loaded');const fail=()=>img.hidden=true;img.addEventListener('load',ok);img.addEventListener('error',fail);if(img.complete)img.naturalWidth?ok():fail();});$$('.code pre').forEach(pre=>{const details=pre.closest('details');if(details&& !$('.open-editor',details)){const b=document.createElement('button');b.className='btn small open-editor';b.textContent='Open in Code Studio';b.dataset.action='editor-from-block';const bar=$('.code-tools',details)||details;bar.appendChild(b);}});}
function assetCard(a){return `<a class="asset-card" href="#/asset/${a.id}"><div class="thumb"><div class="thumb-fallback">${icon(a.category==='Software'?'grid':'chip')}<span>Source photograph</span></div><img src="${esc(a.url)}" alt="${esc(a.title)}" loading="lazy" decoding="async" referrerpolicy="no-referrer"></div><div class="card-info"><span class="badge">${esc(a.category)}</span><h3>${esc(a.title)}</h3><span class="note muted">${a.markers.length?a.markers.length+' guided regions':'Visual reference'} &middot; ${esc(a.owner)}</span></div></a>`;}
function atlas(filter='All',query=''){const categories=['All',...new Set(D.assets.map(a=>a.category))];const rows=D.assets.filter(a=>(filter==='All'||a.category===filter)&&`${a.title} ${a.category}`.toLowerCase().includes(query.toLowerCase()));return `${crumb('Component & interface atlas')}${heading('Recognize it. Understand it. Use it.','Real-source component photographs and actual software interfaces. Open an image to explore its labels, purpose and original documentation.',`<a class="btn" href="#/lesson/wires">Start with the wires ${icon('arrow')}</a>`)}<div class="row wrap between"><div class="filters">${categories.map(c=>`<button class="chip ${filter===c?'active':''}" data-filter-asset="${esc(c)}">${esc(c)}</button>`).join('')}</div><input type="search" id="asset-search" placeholder="Find a component or platform..." value="${esc(query)}" aria-label="Filter component atlas"></div><div class="quality-note"><strong>Real images, original sources.</strong> Photographs load directly from their credited owners. Hover or focus a highlighted region for an explanation; tap on touchscreens. A photograph is not a substitute for the correct electrical pinout.</div><div class="asset-grid" style="margin-top:20px">${rows.map(assetCard).join('')}</div>${rows.length?'':'<div class="empty">No matching component. Try a broader term.</div>'}`;}
function assetView(id){const a=A(id)||A('esp');const first=a.markers[0];return `${crumb(a.title,['atlas','Explore'])}${heading(esc(a.title),'Observe the real object before deciding how to connect or operate it.',`<button class="btn" data-zoom="${a.id}">${icon('fullscreen')} Enlarge</button>`)}<div class="asset-detail-grid"><div>${photo(a.id)}<div class="quality-note"><strong>Orientation matters.</strong> Hover labels refer to the exact source image, not every board sold under a similar name. Connector order, logic voltage and pin assignments must be checked against the actual revision.</div>${a.id.startsWith('pan-')?`<div class="slide-photo-strip">${['pan-parts','pan-fit','pan-side','pan-base','pan-finished'].map(id=>`<a href="#/asset/${id}">${esc(A(id)?.title||id)}</a>`).join('')}</div>`:''}</div><aside class="inspect-panel"><span class="kicker">HOVER &amp; DISCOVER</span><h2 class="inspect-title">${esc(first?.[2]||a.title)}</h2><p class="inspect-text">${esc(first?.[3]||a.note||'Identify the physical features, read the supplier documentation, and record the exact part and board revision in your notebook.')}</p><div class="parts-list">${a.markers.map(([x,y,label,text],i)=>`<button class="${i===0?'active':''}" data-part="${a.id}:${i}">${icon('chip')} ${esc(label)} ${icon('arrow')}</button>`).join('')}</div>${a.markers.length?'':'<p class="small muted">This reference image has no verified spatial pin annotations. Use its original guide instead of guessing a pinout from a generic drawing.</p>'}<div class="callout"><strong>Ask three useful questions.</strong><br>What enters this part?<br>What leaves it?<br>What would a failure look like?</div>${link(a.sourceUrl,'Open the real documentation','btn primary')}<button class="btn quiet small" data-action="narrate-inspect" style="margin-top:12px">${icon('volume')} Hear the explanation</button></aside></div>`;}
function highlightPart(key){const [id,n]=key.split(':'),a=A(id),p=a?.markers[Number(n)];if(!p)return;const panel=$('.inspect-panel');if(panel){$('.inspect-title',panel).textContent=p[2];$('.inspect-text',panel).textContent=p[3];$$('[data-part]',panel).forEach(b=>b.classList.toggle('active',b.dataset.part===key));}else{const f=$(`[data-photo="${id}"]`);if(f){let el=$('.annotation-readout',f);if(!el){el=document.createElement('p');el.className='annotation-readout';el.setAttribute('aria-live','polite');f.appendChild(el);}el.innerHTML=`<strong>${esc(p[2])}.</strong> ${esc(p[3])}`;}}$$('.hotspot').forEach(b=>b.classList.toggle('selected',b.dataset.hotspot===key));}
function buildView(level='All'){const rows=D.projects.filter(p=>level==='All'||p.level===level);return `${crumb('Project studio')}${heading('Build it in stages. Understand every layer.','Start with the outcome, identify the parts, follow the connections, inspect the code and collect evidence. No mystery jumps.',`<a class="btn primary" href="#/project/project-01/0">Your first build ${icon('arrow')}</a>`)}<div class="filters">${['All',...new Set(D.projects.map(p=>p.level))].map(l=>`<button class="chip ${l===level?'active':''}" data-build-level="${l}">${l}</button>`).join('')}</div><div class="project-grid">${rows.map(projectCard).join('')}</div><div class="quality-note">Project thumbnails are original explanatory illustrations, not photographs of finished builds. Inside each project, reference photographs, conceptual designs and native simulator workflows are labelled separately. Hardware and heavy-simulator execution require the specified local setup.</div>`;}
function projectView(id,stage=0){const p=P(id)||D.projects[0],l=L(p.id),n=Math.max(0,Math.min(4,Number(stage)||0));const titles=p.stages;let left='',right='',steps=l.steps;const allAssets=[...new Set([...p.assets,...(p.number===1?['breadboard','resistor']:[]),...(p.number===9?['pan-parts','pan-fit','pan-side','pan-base','pan-finished']:[])])].filter(id=>A(id));
 const selected=p.number===9?[ 'pan-finished','pan-parts','pan-fit','pan-side','pan-finished'][n]:(allAssets[Math.min(n,allAssets.length-1)]||null);
 const codeIndex=l.code.length?0:-1;
 if(n===0){left=(p.number===11?robotMarkup():selected?photo(selected):`<div class="project-outcome-art">${Visuals.art(simArt(p.sim))}<p class="note muted">Illustrated concept / not a simulator screenshot</p></div>`);right=`<span class="kicker">THE OUTCOME / BUILD ${String(p.number).padStart(2,'0')}</span><h2>${esc(p.title)}</h2><p>${esc(p.intro)}</p><div class="callout"><strong>What success means</strong><p>${extractSectionText(l.body,'What you are building')||'A reproducible experiment, a recorded result and a clear explanation of its limits. A successful demo is not a certified product.'}</p></div><div class="component-pills"><span class="badge">${p.level}</span><span class="badge">${p.type}</span><span class="badge">Five stages</span></div><h3 style="margin-top:22px">Before you begin</h3><p>Read the exact board and software requirements, prepare a safe workspace, and keep a notebook. Do not connect a motor or power supply from a photograph alone.</p>`;}
 if(n===1){left=`<div class="stage-title"><span class="kicker">IDENTIFY BEFORE CONNECTING</span><h2>${p.number>=13?'Model & environment':'Your parts, one by one'}</h2></div>${selected?photo(selected):Visuals.art(simArt(p.sim))}<div class="component-pills">${allAssets.map(id=>`<a class="chip" href="#/asset/${id}">${esc(A(id).title)}</a>`).join('')}</div>`;right=`<h3>${p.number>=13?'Software & model prerequisites':'Bill of materials'}</h3><p>Match these requirements to what is actually on your desk or installed on your computer. Similar names do not guarantee compatible parts.</p>${l.tables[0]||'<p>Refer to the full project lesson for environment requirements.</p>'}<div class="callout"><strong>Record the exact revision.</strong> Save a clear photograph or version report. You will need it when a connector, API or default differs from a tutorial.</div>`;}
 if(n===2){left=`<div class="stage-title"><span class="kicker">${p.number>=13?'CONFIGURE THE EXPERIMENT':'POWER OFF FIRST'}</span><h2>${p.number>=13?'Understand the interfaces':'Make every connection explainable'}</h2></div>${p.number===1?circuitWiring():p.number===9?photo('pan-fit'):selected?photo(selected):`<div class="project-outcome-art">${Visuals.art(simArt(p.sim))}</div>`}<p class="quality-note">${p.number===1?'Conceptual series-path illustration; the table gives the reference connections. Check the board revision.':p.number>=13?'Native simulator interfaces and configuration are version-specific. Open the full lesson and matching upstream documentation.':'Reference assembly image, not a wiring instruction. Use the table and datasheet for the actual electrical connections.'}</p>`;right=`<h3>${p.number>=13?'Interfaces & configuration':'Connection table'}</h3>${l.tables[1]||l.tables[0]||''}<h3>Work in small, reversible steps</h3>${steps.slice(0,Math.ceil(steps.length/2)).map((s,i)=>`<div class="step-card"><span class="num">${String(i+1).padStart(2,'0')}</span><p>${esc(s)}</p></div>`).join('')}`;}
 if(n===3){left=`<div class="stage-title"><span class="kicker">UNDERSTAND BEFORE RUNNING</span><h2>${p.number>=13?'Run, observe, record':'Give the hardware a clear behavior'}</h2></div>${selected?photo(selected,{compact:true}):`<div class="project-outcome-art">${Visuals.art(simArt(p.sim))}</div>`}<div class="callout"><strong>Browser vs native execution</strong><p>The Code Studio executes JavaScript and optionally Python through WebAssembly. ESP firmware, ROS 2, Gazebo, MuJoCo and Isaac examples run in their stated local toolchains, not in this page.</p></div>`;right=`<h3>Project code</h3>${codeIndex>=0?l.code.map((c,i)=>`<div class="code-snippet-card"><div class="row between wrap"><strong>${esc(c.title||'Source '+(i+1))}</strong><button class="btn small" data-project-code="${p.id}:${i}">Open in editor ${icon('code')}</button></div><p class="note muted">${esc(c.language||'Source')} &middot; Read the setup and target before executing.</p><pre>${esc(c.text.split('\n').slice(0,10).join('\n'))}${c.text.split('\n').length>10?'\n... full source in Code Studio':''}</pre></div>`).join(''):'<p>This integration project requires assembling the verified native components. Use the full lesson and linked repository instructions rather than pretending a single script implements a whole robot.</p>'}<h3 style="margin-top:24px">Continue the procedure</h3>${steps.slice(Math.ceil(steps.length/2)).map((s,i)=>`<div class="step-card"><span class="num">${String(i+1+Math.ceil(steps.length/2)).padStart(2,'0')}</span><p>${esc(s)}</p></div>`).join('')}`;}
 if(n===4){left=`<div class="stage-title"><span class="kicker">EVIDENCE OVER CONFIDENCE</span><h2>Make the result repeatable.</h2></div>${selected?photo(selected):`<div class="project-outcome-art">${Visuals.art(simArt(p.sim))}</div>`}<div class="actions"><a class="btn primary" href="#/sandbox/${p.sim}">Try the related browser model ${icon('lab')}</a><a class="btn" href="#/lesson/${p.id}/notes">Record the result ${icon('learn')}</a></div>`;right=`<h3>Acceptance & troubleshooting</h3>${l.tables.slice(2).join('')||'<p>Compare measured behavior with the expected observations in the full project lesson.</p>'}<div class="checklist">${['I recorded the exact components and software versions.','I measured an outcome with units and saved the evidence.','I checked one safe failure case and its recovery.','I can explain what this project does not prove.'].map((t,i)=>`<label><input type="checkbox" data-check="evidence-${p.id}-${i}" ${S.checks['evidence-'+p.id+'-'+i]?'checked':''}><span>${t}</span></label>`).join('')}</div><p class="note muted">These are self-reported practice records. The website has not tested your hardware.</p>`;}
 return `${crumb(p.title,['build','Build'])}${heading(esc(p.title),`Build ${String(p.number).padStart(2,'0')} / ${p.level} / ${p.type}`,`<button class="btn" data-action="slideshow">${icon(guidedProject===p.id?'pause':'play')} ${guidedProject===p.id?'Pause slides':'Guided slides'}</button><button class="btn" data-action="narrate-stage">${icon('volume')} Narrate stage</button><a class="btn" href="#/lesson/${p.id}">Full lesson ${icon('learn')}</a>`)}<nav class="stage-steps" aria-label="Project stages">${titles.map((t,i)=>`<a class="${i===n?'active':i<n?'passed':''}" href="#/project/${p.id}/${i}"><span>${String(i+1).padStart(2,'0')}</span>${t}</a>`).join('')}</nav><div class="project-workspace"><section class="stage-panel">${left}</section><section class="stage-panel stage-body">${right}</section></div><div class="stage-nav"><a class="btn" href="#/project/${p.id}/${Math.max(0,n-1)}" ${n===0?'aria-disabled="true"':''}>${icon('back')} Previous stage</a><span class="small muted">${n+1} / 5 &middot; ${esc(titles[n])}</span>${n<4?`<a class="btn primary" href="#/project/${p.id}/${n+1}">Next: ${titles[n+1]} ${icon('arrow')}</a>`:`<a class="btn primary" href="#/project/${D.projects[Math.min(p.number,19)].id}/0">${p.number<20?'Next project':'Review final project'} ${icon('arrow')}</a>`}</div><div class="slide-photo-strip">${allAssets.map(id=>`<a class="btn small" href="#/asset/${id}">${icon('photo')} ${esc(A(id).title)}</a>`).join('')}</div>`;
}
function extractSectionText(html,title){const box=document.createElement('div');box.innerHTML=html;const h=$$('h3',box).find(h=>h.textContent.toLowerCase()===title.toLowerCase());let s='',n=h?.nextElementSibling;while(n&&!/^H[23]$/.test(n.tagName)){if(n.tagName==='P')s+=esc(n.textContent)+' ';n=n.nextElementSibling;}return s;}
function circuitWiring(){return `<div class="wiring-stage"><svg viewBox="0 0 700 300" role="img" aria-label="Series connection from GPIO4 through a 220 ohm resistor and LED anode to cathode and ground."><rect x="25" y="65" width="150" height="165" rx="18" fill="#c9b7e3"/><rect x="50" y="85" width="95" height="70" rx="8" fill="#ebe5f3"/><text x="99" y="118" text-anchor="middle" fill="#594766" font-size="16">ESP32-S3</text><text x="99" y="141" text-anchor="middle" fill="#796787" font-size="12">reference controller</text><circle cx="175" cy="114" r="6" fill="#7555ac"/><circle cx="175" cy="204" r="6" fill="#657768"/><path class="wire" d="M175 114H280" stroke="#9564c0" stroke-width="5" fill="none"/><rect x="280" y="96" width="95" height="36" rx="10" fill="#e7ce9e"/><path d="M300 97v34M322 97v34M353 97v34" stroke="#8c6953" stroke-width="9"/><path class="wire" d="M375 114H475" stroke="#9564c0" stroke-width="5" fill="none"/><circle cx="500" cy="114" r="27" fill="#b18cdc"/><path class="wire" d="M526 114H595V204H175" stroke="#6c9c8b" stroke-width="5" fill="none"/><text x="195" y="99" font-size="13" fill="#76598e">GPIO4</text><text x="326" y="76" text-anchor="middle" font-size="14" fill="#76598e">220 ohm</text><text x="500" y="76" text-anchor="middle" font-size="14" fill="#76598e">LED</text><text x="448" y="153" font-size="12" fill="#76598e">anode +</text><text x="530" y="153" font-size="12" fill="#76598e">cathode -</text><text x="194" y="225" font-size="13" fill="#527c6e">GND</text><text x="350" y="277" text-anchor="middle" font-size="13" fill="#8a7b94">One series path. Power off while changing connections.</text></svg></div>`;}
function sandbox(type='pid'){return `${crumb('Simulation studio')}${heading('Make an idea move.','Six local, interactive teaching models. Change a variable, inspect the output, and export the actual calculation.',`<button class="btn" data-action="lab-focus">${icon('fullscreen')} Focus lab</button><a class="btn" href="#/module/09">Native simulator guides ${icon('arrow')}</a>`)}<div class="filters">${Object.entries(Labs.names).map(([id,name])=>`<a class="chip ${type===id?'active':''}" href="#/sandbox/${id}">${({circuit:'Circuit',pid:'PID motor',rover:'Rover',arm:'Robot arm',path:'A* planner',rl:'Q-learning'})[id]}</a>`).join('')}</div><div id="lab-container"></div>`;}
const presets={
 circuit:{name:'LED current sweep',lang:'javascript',text:`// Change a value. Predict the result before running.\nconst supply = 3.3;      // volts\nconst ledDrop = 2.0;     // simplified constant drop\nconst resistances = [100, 150, 220, 330, 470, 680, 1000];\nconst points = resistances.map(r => {\n  const result = Engine.ohms(supply, r, ledDrop);\n  console.log(r + ' ohm -> ' + result.milliamps.toFixed(2) + ' mA');\n  return [r, result.milliamps];\n});\nplot(points, 'Resistance (ohm) vs current (mA)');\n// What changes when the switch opens?\nconsole.log('Open switch:', Engine.ohms(supply, 220, ledDrop, false));`},
 pid:{name:'PID joint experiment',lang:'javascript',text:`// SI units: radians, seconds, N m, kg m2.\nconst parameters = {\n  kp: 10, ki: 1, kd: 3,\n  inertia: 0.5, damping: 0.4, target: 1,\n  limit: 5, seconds: 8\n};\nconst result = Engine.pid(parameters);\nconst last = result[result.length - 1];\nconst peak = Math.max(...result.map(row => row.position));\nconsole.log('Final state:', last);\nconsole.log('Peak overshoot (%):', Math.max(0, (peak - 1) * 100));\nplot(result.map(row => [row.t, row.position]),\n     'Time (s) vs joint position (rad)');\n// Change inertia to 1.0 and explain what happened.`},
 planner:{name:'A* search with a blocked cell',lang:'javascript',text:`// Grid coordinates: [column, row]. Four-connected motion.\nconst walls = new Set(['2,1', '2,2', '2,3']);\nconst result = Engine.astar(6, 5, walls, [0,0], [5,4]);\nconsole.log('Path:', result.path);\nconsole.log('Cost:', result.cost);\nconsole.log('Explored cells:', result.visited.length);\nplot(result.path, 'Grid path: x column vs y row');\n// Add a full vertical wall. The correct result is no path.\nfor (let y = 0; y < 5; y++) walls.add('3,' + y);\nconsole.log('Blocked route:', Engine.astar(6, 5, walls, [0,0], [5,4]));`},
 learning:{name:'Train and evaluate Q-learning',lang:'javascript',text:`// This is an actual table update, not a fabricated learning curve.\nconst learner = new Engine.GridLearner(42);\nconsole.log('Untrained policy:', learner.evaluate(false, 100));\nlearner.train(1000);\nconsole.log('Trained policy:', learner.evaluate(false, 100));\nconsole.log('Greedy rollout:', learner.rollout());\n// Average returns in non-overlapping batches of 25 episodes.\nconst batches = [];\nfor (let i = 0; i < learner.history.length; i += 25) {\n  const rows = learner.history.slice(i, i + 25);\n  batches.push([i + rows.length,\n    rows.reduce((sum, row) => sum + row.reward, 0) / rows.length]);\n}\nplot(batches, 'Training episodes vs mean return');`},
 python:{name:'Python: two-link forward kinematics',lang:'python',text:`# Runs with optional online Pyodide, not a native ROS installation.\nimport math\n\nlink1, link2 = 0.15, 0.11  # metres\nshoulder, elbow = math.radians(30), math.radians(45)\nx = link1 * math.cos(shoulder) + link2 * math.cos(shoulder + elbow)\ny = link1 * math.sin(shoulder) + link2 * math.sin(shoulder + elbow)\nprint(f'Tool position: x={x:.4f} m, y={y:.4f} m')\nprint(f'Reach: {math.hypot(x, y):.4f} m')\n\n# Follow the tip as the shoulder moves.\npoints = []\nfor degrees in range(-30, 91, 3):\n    q = math.radians(degrees)\n    points.append([link1 * math.cos(q) + link2 * math.cos(q + elbow),\n                   link1 * math.sin(q) + link2 * math.sin(q + elbow)])\nplot(points, 'Tool x (m) vs tool y (m)')`}
};
function editor(){const initial=editorDraft||S.drafts.active||{...presets.circuit};const lang=initial.lang||'javascript';editorDraft=initial;return `${crumb('Code studio')}${heading('Change the code. See the consequence.','A real worker-backed editor with plots, output, timeout protection and saved drafts. No hidden remote execution.',`<button class="btn" data-action="import-code">Open file ${icon('folder')}</button><button class="btn" data-action="export-code">Download code ${icon('download')}</button>`)}<div class="editor-layout"><section class="editor-panel"><div class="editor-toolbar"><div class="row wrap"><span class="caps muted">${icon('code')} PLAYGROUND</span><select id="code-lang" aria-label="Execution language"><option value="javascript" ${lang==='javascript'?'selected':''}>JavaScript / offline</option><option value="python" ${lang==='python'?'selected':''}>Python / online runtime</option><option value="native" ${!['javascript','python'].includes(lang)?'selected':''}>Native source / export only</option></select></div><select id="code-preset" aria-label="Load example"><option value="">Load an example...</option>${Object.entries(presets).map(([id,p])=>`<option value="${id}">${p.name}</option>`).join('')}</select></div><div class="editor-wrap"><div class="line-numbers" aria-hidden="true"></div><textarea id="code-input" spellcheck="false" autocapitalize="off" autocomplete="off" aria-label="Editable source code" wrap="off">${esc(initial.text||'')}</textarea></div><div class="editor-footer"><span id="runtime-label" class="small muted">${runtimeLabel(lang)}</span><div class="actions"><button class="btn small" data-action="stop-code" id="stop-code" disabled>Stop</button><button class="btn primary" data-action="run-code" id="run-code">Run code ${icon('play')}</button></div></div></section><aside class="output-panel"><div class="row between"><h3>Experiment output</h3><span id="code-state" class="badge">READY</span></div><pre class="terminal" id="code-output" role="log" aria-live="polite">Output appears here. Run the example to begin.</pre><canvas id="code-chart" width="640" height="260" style="width:100%;height:240px" aria-label="Plot generated by your code"></canvas><div class="api-docs"><h4>Small API. Clear behavior.</h4><p><code>console.log(value)</code> sends text to the output.<br><code>plot([[x,y], ...], title)</code> draws your data.<br><code>Engine</code> exposes the six teaching models in JavaScript.</p><p class="note muted">Ctrl/Cmd + Enter runs. JavaScript stops after 5 seconds. Python runs in a separate optional worker; initial runtime download requires internet. Stop terminates that worker. Native firmware, ROS and simulator source is editable but not compiled here.</p></div></aside></div><div class="quality-note"><strong>Run code you understand.</strong> Workers isolate computations from the page DOM, but this is an educational editor, not a hardened environment for hostile code. Python packages and native device drivers are not interchangeable with browser JavaScript.</div>`;}
function runtimeLabel(lang){return lang==='javascript'?'Local JavaScript worker / 5 s execution limit':lang==='python'?'Pyodide v314.0.4 / internet needed for runtime download':'Native toolchain required / editable and downloadable only';}
function initEditor(){const input=$('#code-input');if(!input)return;const update=()=>{const n=input.value.split('\n').length;$('.line-numbers').textContent=Array.from({length:n},(_,i)=>i+1).join('\n');editorDraft={name:'My draft',lang:$('#code-lang').value,text:input.value};S.drafts.active=editorDraft;save();};input.addEventListener('input',update);input.addEventListener('scroll',()=>$('.line-numbers').scrollTop=input.scrollTop);input.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const start=input.selectionStart,end=input.selectionEnd;input.setRangeText('  ',start,end,'end');update();}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();runCode();}});$('#code-lang').addEventListener('change',()=>{stopCode(false);update();$('#runtime-label').textContent=runtimeLabel($('#code-lang').value);});$('#code-preset').addEventListener('change',e=>{if(!presets[e.target.value])return;const p=presets[e.target.value];input.value=p.text;$('#code-lang').value=p.lang;$('#runtime-label').textContent=runtimeLabel(p.lang);update();stopCode(false);});update();drawPlot([], 'Run an example to generate a plot.');}
function appendOutput(value){const out=$('#code-output');if(!out)return;const str=typeof value==='string'?value:JSON.stringify(value,null,2);out.textContent=(out.textContent+'\n'+str).slice(-40000);out.scrollTop=out.scrollHeight;}
function stopCode(message=true){if(codeWorker){codeWorker.terminate();codeWorker=null;if(message)appendOutput('Stopped. The worker was terminated.');}clearTimeout(codeTimer);codeTimer=null;const run=$('#run-code'),stop=$('#stop-code');if(run)run.disabled=false;if(stop)stop.disabled=true;const state=$('#code-state');if(state&&message)state.textContent='STOPPED';}
function runCode(){if(!$('#code-input'))return;stopCode(false);const lang=$('#code-lang').value,code=$('#code-input').value;if(lang==='native'){appendOutput('This source requires its native compiler or simulator. Download it, then follow the versioned project setup. It was not executed in this browser.');return;}$('#code-output').textContent='';$('#run-code').disabled=true;$('#stop-code').disabled=false;$('#code-state').textContent=lang==='python'?'LOADING PYTHON':'RUNNING';
 const common=`const stringify=v=>{try{return typeof v==='string'?v:JSON.stringify(v);}catch{return String(v);}};let count=0;const log=(...v)=>{if(count++<500)postMessage({type:'log',text:v.map(stringify).join(' ')});};const plot=(points,title='Plot')=>{if(!Array.isArray(points)||points.length>20000)throw Error('plot expects at most 20000 [x,y] points.');postMessage({type:'plot',points,title:String(title)});};`;
 let source;if(lang==='javascript'){source=window.ENGINE_SOURCE+'\n'+common+`\nself.onmessage=async e=>{try{const localConsole={log,warn:log,error:log,info:log};await new Function('console','plot','Engine','"use strict";return (async()=>{\\n'+e.data+'\\n})();')(localConsole,plot,Engine);postMessage({type:'done'});}catch(e){postMessage({type:'error',text:e.name+': '+e.message});}};`;}else{source=common+`\nself.onmessage=async e=>{try{postMessage({type:'status',text:'Downloading the optional Python runtime...'});importScripts('https://cdn.jsdelivr.net/pyodide/v314.0.4/full/pyodide.js');const py=await loadPyodide({indexURL:'https://cdn.jsdelivr.net/pyodide/v314.0.4/full/'});py.setStdout({batched:log});py.setStderr({batched:log});await py.runPythonAsync("import json, js\\ndef plot(points, title='Plot'):\\n    js.postMessage(js.JSON.parse(json.dumps({'type':'plot','points':points,'title':title})))");postMessage({type:'status',text:'Python loaded. Running...'});await py.runPythonAsync(e.data);postMessage({type:'done'});}catch(e){postMessage({type:'error',text:'Python: '+e.message+'\\nRuntime download may be blocked or offline. Download the source to run it in your own Python environment.'});}};`;}
 const url=URL.createObjectURL(new Blob([source],{type:'application/javascript'}));try{codeWorker=new Worker(url);}catch(e){URL.revokeObjectURL(url);appendOutput('Worker unavailable: '+e.message);stopCode(false);return;}URL.revokeObjectURL(url);const token=routeToken;codeWorker.onmessage=e=>{if(routeToken!==token)return;const m=e.data;if(m.type==='log'||m.type==='status')appendOutput(m.text);if(m.type==='plot')drawPlot(m.points,m.title);if(m.type==='done'){appendOutput('\nExecution complete.');$('#code-state').textContent='COMPLETE';stopCode(false);}if(m.type==='error'){appendOutput(m.text);$('#code-state').textContent='ERROR';stopCode(false);}};codeWorker.onerror=e=>{appendOutput('Worker error: '+e.message);if($('#code-state'))$('#code-state').textContent='ERROR';stopCode(false);};codeWorker.postMessage(code);codeTimer=setTimeout(()=>{appendOutput(lang==='javascript'?'Time limit reached (5 seconds). The calculation was stopped.':'The Python session exceeded its 90-second setup/run allowance. Check connectivity or reduce the workload.');if($('#code-state'))$('#code-state').textContent='TIME LIMIT';stopCode(false);},lang==='javascript'?5000:90000);}
function drawPlot(points,title){const cv=$('#code-chart');if(!cv)return;const c=cv.getContext('2d'),w=cv.width,h=cv.height;c.fillStyle='#f8f6fc';c.fillRect(0,0,w,h);c.font='13px sans-serif';c.fillStyle='#80718e';c.textAlign='left';c.fillText(String(title).slice(0,70),25,25);const pts=Array.isArray(points)?points.filter(p=>Array.isArray(p)&&p.length>=2&&Number.isFinite(p[0])&&Number.isFinite(p[1])).slice(0,20000):[];if(!pts.length)return;const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]);let xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);if(xmax===xmin)xmax=xmin+1;if(ymax===ymin)ymax=ymin+1;const lx=55,rx=w-24,ty=43,by=h-35;for(let i=0;i<=4;i++){const y=ty+(by-ty)*i/4;c.strokeStyle='#e8e1f0';c.beginPath();c.moveTo(lx,y);c.lineTo(rx,y);c.stroke();c.fillStyle='#95899f';c.font='11px monospace';c.fillText((ymax-(ymax-ymin)*i/4).toFixed(2),4,y+4);}c.strokeStyle='#8662c2';c.lineWidth=2.5;c.beginPath();pts.forEach(([x,y],i)=>{const px=lx+(x-xmin)/(xmax-xmin)*(rx-lx),py=by-(y-ymin)/(ymax-ymin)*(by-ty);i?c.lineTo(px,py):c.moveTo(px,py);});c.stroke();c.fillStyle='#95899f';c.fillText(xmin.toFixed(2),lx,by+22);c.textAlign='right';c.fillText(xmax.toFixed(2),rx,by+22);}
const clips=[{id:'pid',title:'Watch a feedback loop settle',desc:'Original computed teaching model. See overshoot and recovery, then change the gains yourself.',sim:'pid'},{id:'arm',title:'Follow a reachable target',desc:'Two-link analytical kinematics. Observe how joint angles combine into a tool position.',sim:'arm'},{id:'learning',title:'See Q-learning change a policy',desc:'Actual tabular training snapshots on a toy grid. Not a native Isaac or MuJoCo recording.',sim:'rl'}];
function library(){return `${crumb('Reference & media library')}${heading('Learn from the source. Then make it yours.','Verified source categories, practical GitHub assignments and playable local demonstrations. Native tutorials remain linked to their original maintainers.',`<button class="btn" data-action="add-resource">Add my resource +</button>`)}<div class="section-heading"><div><h2>Watch a model. Then play with it.</h2><p>These bundled teaching clips work without YouTube. Each has a live, editable experiment.</p></div></div><div class="video-grid">${clips.map(v=>`<article class="video-card"><button class="video-poster" data-local-video="${v.id}" aria-label="Play ${v.title}">${Visuals.art(simArt(v.sim))}<span class="play-circle">${icon('play')}</span><span class="badge">OFFLINE TEACHING CLIP</span></button><div class="video-caption"><h3>${v.title}</h3><p>${v.desc}</p><a class="btn quiet small" href="#/sandbox/${v.sim}">Try the live experiment ${icon('arrow')}</a></div></article>`).join('')}</div><div class="section-heading"><div><h2>Real platforms. Actual reference recordings.</h2><p>External players load only after you choose to play. Owner permissions, network policy and browser origin can still block embedding.</p></div></div><div class="video-grid"><article class="video-card"><button class="video-poster" data-youtube="P83tKA1iz2Y" aria-label="Load the official MuJoCo viewer recording">${Visuals.art('arm')}<span class="play-circle">${icon('play')}</span><span class="badge">MUJOCO / SOURCE RECORDING</span></button><div class="video-caption"><h3>Inside the real MuJoCo viewer</h3><p>Pause the source recording and find the simulation controls, display panels and viewport.</p>${link('https://mujoco.readthedocs.io/en/stable/programming/samples.html','Official viewer documentation','btn quiet small')}</div></article><article class="video-card"><button class="video-poster" data-youtube="eFsRiT6e2EU" aria-label="Load historical Adafruit reference rover demonstration">${Visuals.art('rover')}<span class="play-circle">${icon('play')}</span><span class="badge">HISTORICAL REFERENCE BUILD</span></button><div class="video-caption"><h3>A real Raspberry Pi rover</h3><p>A historical Adafruit reference, not a drop-in current wiring recipe. Compare the build with Project 12.</p>${link('https://learn.adafruit.com/simple-raspberry-pi-robot?view=all','Original build guide','btn quiet small')}</div></article><article class="video-card"><a class="video-poster" href="https://modernrobotics.northwestern.edu/nu-gm-book-resource/foundations-of-robot-motion/" target="_blank" rel="noopener">${Visuals.art('pid')}<span class="play-circle">${icon('external')}</span><span class="badge">OFFICIAL VIDEO COURSE</span></a><div class="video-caption"><h3>Modern Robotics, explained visually</h3><p>Work through the course's own chapter-by-chapter videos, then reproduce the kinematics in the arm lab.</p>${link('https://modernrobotics.northwestern.edu/nu-gm-book-resource/foundations-of-robot-motion/','Open the course videos','btn quiet small')}</div></article></div><div class="quality-note"><strong>Reliable fallback, not a playback guarantee.</strong> For external embeds, serve this website over localhost or HTTPS rather than opening a file URL. The included launcher does that. If an owner disables embedding, use the direct source link; the local experiments and bundled clips still work.</div><div class="section-heading"><div><h2>Open-source projects with a learning mission</h2><p>Do not collect repositories. Read a subsystem, reproduce it, change it and measure the difference.</p></div></div><div class="resource-grid">${D.repos.map((r,i)=>`<article class="resource-card"><div class="row between"><span class="tile-icon ${['','mint','blue','peach'][i%4]}">${icon('code')}</span><span class="badge">${esc(r.category)}</span></div><h3>${esc(r.name)}</h3><p>${esc(r.description)}</p><div class="assignment"><span class="caps">YOUR ASSIGNMENT</span><p>${esc(r.assignment)}</p></div>${link(r.url,'Explore repository','btn quiet small')}</article>`).join('')}</div><div class="section-heading"><div><h2>Go deeper, at your own pace</h2><p>Original university material and official technical documentation.</p></div></div><div class="resource-grid">${[...D.resources,...S.custom].map(r=>`<article class="resource-card"><span class="badge">${esc(r.type||'Your resource')}</span><h3>${esc(r.title)}</h3><p>${esc(r.why||r.org||'Saved in your workspace.')}</p>${link(r.url,'Open original source','btn quiet small')}</article>`).join('')}</div><div class="quality-note"><strong>Attribution and reuse.</strong> Photographs, software screenshots, videos and repositories remain subject to their owners' licenses. This study workspace does not grant resale rights to third-party media. Review each asset's license before publishing a commercial course.</div>`;}
function settings(){return `${crumb('Your workspace')}${heading('Make this feel like your workshop.','Customize appearance, pace and accessibility. Your notes and progress stay in this browser unless you export them.',`<button class="btn primary" data-action="export-progress">Back up my progress ${icon('download')}</button>`)}<div class="settings-grid"><section class="panel"><span class="kicker">LOOK &amp; FEEL</span><div class="setting-row"><div><h4>A palette that feels right</h4><p>Soft contrast, clear hierarchy and a little personality.</p></div><div class="swatches">${[['violet','#7256e8','Violet'],['ocean','#157da0','Ocean'],['ember','#b34f35','Ember']].map(([v,c,label])=>`<button class="swatch ${S.theme===v?'active':''}" style="background:${c}" data-theme-choice="${v}" aria-label="${label} theme" title="${label}"></button>`).join('')}</div></div><div class="setting-row"><div><h4>Appearance</h4><p>Light or dark, independent of your color palette.</p></div><select data-setting="mode" aria-label="Appearance"><option value="light" ${S.mode==='light'?'selected':''}>Light</option><option value="dark" ${S.mode==='dark'?'selected':''}>Dark</option></select></div><div class="setting-row"><div><h4>Reading size</h4><p>Change the text without losing the layout.</p></div><select data-setting="scale" aria-label="Text size">${[[.9,'Compact'],[1,'Standard'],[1.12,'Comfort'],[1.2,'Large']].map(([v,n])=>`<option value="${v}" ${Number(S.scale)===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="setting-row"><div><h4>Motion</h4><p>Reduce decorative motion. Running experiments remain visible because motion is their result.</p></div><select data-setting="motion" aria-label="Motion preference"><option value="auto" ${S.motion==='auto'?'selected':''}>Follow device</option><option value="full" ${S.motion==='full'?'selected':''}>Full motion</option><option value="reduced" ${S.motion==='reduced'?'selected':''}>Reduced</option></select></div><div class="setting-row"><div><h4>Narration speed</h4><p>Uses your browser's available speech voice. Start it explicitly in a lesson.</p></div><select data-setting="rate" aria-label="Narration speed">${[.8,1,1.15,1.3].map(v=>`<option value="${v}" ${Number(S.rate)===v?'selected':''}>${v}x</option>`).join('')}</select></div><button class="btn small" data-action="voice-test">${icon('volume')} Test my narration voice</button></section><section class="panel"><span class="kicker">YOUR LEARNING ROUTINE</span><div class="form-field"><label for="learner-name">What should we call you?</label><input id="learner-name" data-setting="name" value="${esc(S.name)}" maxlength="40"></div><div class="form-field"><label for="learn-hours">Weekly study target</label><select id="learn-hours" data-setting="hours">${[3,6,9,12,15].map(h=>`<option value="${h}" ${Number(S.hours)===h?'selected':''}>${h} hours / week</option>`).join('')}</select><p class="note muted">Planning preference only. Mastery is measured by demonstrated skill, not elapsed hours.</p></div><h4 style="margin-top:20px">A balanced week</h4><div class="checklist"><p><strong>${Math.round(Number(S.hours)*.3*10)/10} h</strong> &middot; Learn and explain a concept.</p><p><strong>${Math.round(Number(S.hours)*.5*10)/10} h</strong> &middot; Build, simulate and debug.</p><p><strong>${Math.round(Number(S.hours)*.2*10)/10} h</strong> &middot; Record evidence, retrieve knowledge and teach.</p></div><div class="callout"><strong>Make the next action small.</strong> One measurement, one explanation or one tested failure is a better finish line than "become an expert tonight."</div></section><section class="panel"><span class="kicker">YOUR DATA, YOUR CONTROL</span><h3>A notebook you can keep.</h3><p class="muted">Export settings, notes, lesson reviews, quiz choices and the active code draft as JSON. Import it on another browser to continue.</p><div class="actions"><button class="btn" data-action="export-progress">${icon('download')} Export JSON</button><button class="btn" data-action="import-progress">Import JSON</button></div><p class="note muted" style="margin-top:14px">No account, cloud synchronization or background tracking is built into this file. External images and requested videos do contact their hosting providers.</p></section><section class="panel"><span class="kicker">KEYBOARD &amp; ACCESSIBILITY</span><div class="checklist"><p><strong>/</strong> &middot; Search lessons, components and projects.</p><p><strong>Escape</strong> &middot; Close dialogs and stop narration.</p><p><strong>Ctrl/Cmd + Enter</strong> &middot; Run the code editor.</p><p><strong>Arrow keys</strong> &middot; Rotate the focused 3D concept.</p><p><strong>E</strong> &middot; Explode the focused concept.</p></div><p class="note muted">Photo hotspots support keyboard focus and tapping as well as mouse hover. Readouts and tables keep the concepts available without animation.</p></section></div>`;}
function dialog(title,body){const d=$('#modal');d.innerHTML=`<header class="dialog-head"><h2>${title}</h2><button class="close icon-btn" data-close aria-label="Close dialog">${icon('close')}</button></header><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();return d;}
function closeDialog(){const d=$('#modal');d.querySelectorAll('video').forEach(v=>v.pause());d.querySelectorAll('iframe').forEach(i=>i.remove());d.close();}
function openSearch(){dialog('What are you curious about?',`<input id="global-search" type="search" style="width:100%" placeholder="Try: torque, Gazebo, sensor, motor..." aria-label="Search all learning content"><div class="search-results" id="search-results"></div>`);const input=$('#global-search');input.focus();const render=()=>{const q=input.value.toLowerCase().trim();const rows=[...D.lessons.map(l=>({title:l.title,type:l.kind==='project'?'Project lesson':'Lesson',href:'#/lesson/'+l.id,hay:l.title+' '+l.intro})),...D.assets.map(a=>({title:a.title,type:'Real-source visual',href:'#/asset/'+a.id,hay:a.title+' '+a.category}))].filter(x=>!q||x.hay.toLowerCase().includes(q)).slice(0,18);$('#search-results').innerHTML=rows.map(x=>`<a href="${x.href}" data-close><span><strong>${esc(x.title)}</strong><small>${x.type}</small></span>${icon('arrow')}</a>`).join('')||'<p class="muted">No direct match. Try a broader concept.</p>';};input.addEventListener('input',render);render();}
function zoomPhoto(id){const a=A(id);if(!a)return;dialog(esc(a.title),`<div class="dialog-photo">${photo(id,{hotspots:true})}</div><p class="muted small">${esc(a.note||'Source reference image. Check the exact hardware or software version.')}</p>`);hydrateMedia();}
let ytPromise;
function youtubeAPI(){if(window.YT?.Player)return Promise.resolve(window.YT);if(ytPromise)return ytPromise;ytPromise=new Promise((resolve,reject)=>{const timer=setTimeout(()=>{ytPromise=null;reject(Error('The external player did not initialize.'));},10000);window.onYouTubeIframeAPIReady=()=>{clearTimeout(timer);resolve(window.YT);};const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.referrerPolicy='strict-origin-when-cross-origin';script.onerror=()=>{clearTimeout(timer);ytPromise=null;script.remove();reject(Error('The video service could not be reached.'));};document.head.appendChild(script);});return ytPromise;}
async function playYoutube(id){if(!/^[a-zA-Z0-9_-]{11}$/.test(id))return;dialog('Source video',`<div class="media-player"><div id="yt-target"></div></div><p id="yt-status" role="status" class="quality-note">${location.protocol==='file:'?'This file is not served from a web origin. YouTube may reject local-file embedding. Use the included localhost launcher or the direct link below.':'Requesting the original source player. Embedding is controlled by the owner and your network.'}</p><div class="actions">${link('https://www.youtube.com/watch?v='+id,'Watch directly on YouTube','btn primary')}<a class="btn" href="#/library" data-close>Use offline teaching clips</a></div>`);try{const YT=await youtubeAPI();if(!$('#modal').open||!$('#yt-target'))return;const options={host:'https://www.youtube-nocookie.com',videoId:id,width:'100%',height:'420',playerVars:{playsinline:1,rel:0,autoplay:0},events:{onReady:e=>{const iframe=e.target.getIframe();iframe.referrerPolicy='strict-origin-when-cross-origin';if($('#yt-status'))$('#yt-status').textContent='Player initialized. Press Play. If the video is restricted, use the direct source link.';},onError:e=>{const errors={100:'This video is missing or private.',101:'The owner does not allow embedding.',150:'The owner does not allow embedding.',153:'The service could not verify the embedding client/referrer.'};if($('#yt-status'))$('#yt-status').textContent=(errors[e.data]||'The video service reported a playback error.')+' Use the direct source link; this is not evidence that your robotics setup is broken.';}}};if(location.protocol==='http:'||location.protocol==='https:')options.playerVars.origin=location.origin;new YT.Player('yt-target',options);}catch(e){if($('#yt-status'))$('#yt-status').textContent=e.message+' Use the direct source link. Bundled teaching clips and live simulations remain available.';}}
function playLocalVideo(id){const c=clips.find(v=>v.id===id),src=window.KINETIC_VIDEOS?.[id];if(!c)return;if(!src){dialog(c.title,`<p>This clip is not bundled in this build. The corresponding live computation is available.</p><a class="btn primary" href="#/sandbox/${c.sim}" data-close>Open the live experiment</a>`);return;}dialog(c.title,`<div class="media-player"><video controls playsinline preload="metadata" style="width:100%;max-height:65vh" src="${src}" aria-label="${esc(c.title)}"></video></div><p class="quality-note">${c.desc} This clip has no audio; the explanation below is its transcript.</p><h3>What to notice</h3><p>${id==='pid'?'The target is fixed, but the measured position changes over time. The controller reacts to error. A larger proportional gain is not automatically a better response: compare overshoot, settling and torque saturation.':id==='arm'?'The arm has two fixed-length links. The target traces a path in the reachable workspace. The solver calculates joint angles; the links do not stretch. Collision, speed and torque limits would need an additional planner and controller.':'Every training episode interacts with the same grid. Q-values update from reward and the estimated future value. Arrows show a greedy action for each free cell. Improvements on this small map do not establish general robot intelligence.'}</p><a class="btn primary" href="#/sandbox/${c.sim}" data-close>Change it yourself ${icon('lab')}</a>`);}
function speak(text,el){if(!('speechSynthesis'in window)){toast('Speech synthesis is not available in this browser. The full text remains readable.');return;}if(speechSynthesis.speaking){speechSynthesis.cancel();$$('.reading-active').forEach(e=>e.classList.remove('reading-active'));toast('Narration stopped.');return;}speechSynthesis.cancel();const clean=String(text).replace(/\s+/g,' ').slice(0,13000);const chunks=clean.match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[clean];const batches=[];let current='';for(const sentence of chunks){if((current+sentence).length>750&&current){batches.push(current);current='';}current+=sentence;}if(current)batches.push(current);if(el)el.classList.add('reading-active');let index=0;const next=()=>{if(index>=batches.length){el?.classList.remove('reading-active');return;}const u=new SpeechSynthesisUtterance(batches[index++]);u.lang='en-US';u.rate=Number(S.rate)||1;u.onend=next;u.onerror=()=>{el?.classList.remove('reading-active');};speechSynthesis.speak(u);};next();toast('Narrating. Press Escape or Read aloud again to stop.');}
const glossary={GPIO:'General-purpose input/output: a configurable signal pin, not a motor power supply.',PWM:'Pulse-width modulation: change how long a digital signal stays high in each cycle.',PID:'A feedback controller combining present error, accumulated error and the rate of change.',torque:'A turning effect. Torque depends on force and distance from the joint axis.',odometry:'Estimating motion by accumulating small measured movements; errors accumulate too.',URDF:'Unified Robot Description Format: an XML description of links and joints.',MJCF:'MuJoCo model format: describes a physical model for the MuJoCo engine.',SDF:'Simulation Description Format: describes simulation worlds, models, sensors and systems.',latency:'Delay between an event and its observable response. Average delay alone can hide unsafe worst cases.',calibration:'Comparing a measurement or model with known references and estimating correction parameters.',SLAM:'Simultaneous localization and mapping: estimate a map and the robot location within it.',kinematics:'The geometry of motion without calculating the forces that cause it.'};
function enrichGlossary(){const el=$('#lesson-body');if(!el)return;const used=new Set(),walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode()){const n=walker.currentNode;if(!n.parentElement.closest('a,button,code,pre,h1,h2,h3,h4,summary,script,style,textarea')&&n.textContent.trim())nodes.push(n);}for(const n of nodes){let text=n.textContent;const pattern=new RegExp('\\b('+Object.keys(glossary).join('|')+')\\b','gi');let match,parts=[],last=0;while((match=pattern.exec(text))){const key=Object.keys(glossary).find(k=>k.toLowerCase()===match[0].toLowerCase());if(used.has(key))continue;used.add(key);parts.push(document.createTextNode(text.slice(last,match.index)));const b=document.createElement('span');b.className='glossary-term';b.tabIndex=0;b.textContent=match[0];const tip=document.createElement('span');tip.className='glossary-tip';tip.textContent=glossary[key];b.appendChild(tip);parts.push(b);last=match.index+match[0].length;}if(parts.length){parts.push(document.createTextNode(text.slice(last)));const frag=document.createDocumentFragment();parts.forEach(p=>frag.appendChild(p));n.replaceWith(frag);}}}
function addResource(){dialog('A useful source worth keeping',`<form id="resource-form"><div class="form-field"><label for="resource-title">Title</label><input id="resource-title" required maxlength="120" placeholder="A course, repository or build log"></div><div class="form-field"><label for="resource-url">Source URL</label><input id="resource-url" type="url" required placeholder="https://..."></div><div class="form-field"><label for="resource-why">What will you learn or build?</label><textarea id="resource-why" rows="3" maxlength="800"></textarea></div><button class="btn primary" type="submit">Save to my library</button></form>`);$('#resource-form').addEventListener('submit',e=>{e.preventDefault();const url=safeURL($('#resource-url').value);if(url==='#'){toast('Use a valid http or https source URL.');return;}S.custom.push({title:$('#resource-title').value,url,why:$('#resource-why').value,type:'Your resource'});S.custom=S.custom.slice(-100);save();closeDialog();render(true);toast('Resource saved to your local library.');});}
function importProgress(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const f=input.files[0];if(!f)return;if(f.size>5000000){toast('This file is too large. Use a Kinetic progress JSON under 5 MB.');return;}try{const o=JSON.parse(await f.text());if(o.version!==1||typeof o.complete!=='object'||typeof o.notes!=='object')throw Error('Not a compatible Kinetic progress export.');const n={...defaults};n.name=String(o.name||'Learner').slice(0,40);if(['violet','ocean','ember'].includes(o.theme))n.theme=o.theme;if(['dark','light'].includes(o.mode))n.mode=o.mode;if(['auto','full','reduced'].includes(o.motion))n.motion=o.motion;n.scale=Math.max(.85,Math.min(1.25,Number(o.scale)||1));n.rate=Math.max(.7,Math.min(1.5,Number(o.rate)||1));n.hours=Math.max(1,Math.min(40,Number(o.hours)||6));if(['beginner','software','advanced'].includes(o.path))n.path=o.path;if(L(o.lastLesson))n.lastLesson=o.lastLesson;for(const k of ['complete','quizzes','notes','checks']){n[k]={};for(const [id,v]of Object.entries(o[k]||{}).slice(0,3000)){if(['__proto__','prototype','constructor'].includes(id))continue;if(k==='notes')n[k][id]=String(v).slice(0,50000);else if(k==='quizzes'&&Number.isInteger(v)&&v>=0&&v<20)n[k][id]=v;else if(k==='complete'||k==='checks')n[k][id]=!!v;}}n.dashboard=StudioUI.sanitize(o.dashboard);n.drafts={};if(o.drafts?.active&&typeof o.drafts.active.text==='string')n.drafts.active={text:o.drafts.active.text.slice(0,200000),lang:['javascript','python','native'].includes(o.drafts.active.lang)?o.drafts.active.lang:'native',name:'Imported draft'};n.custom=(Array.isArray(o.custom)?o.custom:[]).slice(0,100).filter(r=>safeURL(r.url)!=='#').map(r=>({title:String(r.title).slice(0,120),url:safeURL(r.url),why:String(r.why||'').slice(0,800),type:'Your resource'}));S=n;editorDraft=null;save();appearance();header();render();toast('Progress imported. Your local workspace has been restored.');}catch(e){toast('Import failed: '+e.message);}};input.click();}
function importCode(){const input=document.createElement('input');input.type='file';input.accept='.js,.py,.cpp,.c,.h,.xml,.sdf,.urdf,.txt';input.onchange=async()=>{const f=input.files[0];if(!f)return;if(f.size>250000){toast('Use a source file smaller than 250 KB.');return;}editorDraft={name:f.name,text:await f.text(),lang:f.name.endsWith('.js')?'javascript':f.name.endsWith('.py')?'python':'native'};S.drafts.active=editorDraft;save();render();};input.click();}
function setEditorFromProject(key){const [id,n]=key.split(':'),source=L(id)?.code[Number(n)];if(!source)return;editorDraft={name:source.title,text:source.text,lang:'native'};S.drafts.active=editorDraft;save();location.hash='/code';toast('Native project source opened for inspection and download. Choose an appropriate local toolchain to execute it.');}
function render(preserve=false){const y=preserve?scrollY:0;dispose();routeToken++;const fragment=location.hash.replace(/^#\/?/,'')||'home';route=fragment.split('/').map(s=>{try{return decodeURIComponent(s);}catch{return s;}});const [view,id,sub]=route;let html;switch(view){case 'learn':html=learn();break;case 'module':html=moduleView(id,sub);break;case 'lesson':html=lessonView(id,sub);break;case 'build':html=buildView(id||'All');break;case 'project':html=projectView(id,sub);break;case 'sandbox':html=sandbox(Labs.names[id]?id:'pid');break;case 'code':html=editor();break;case 'atlas':html=atlas(id||'All',sub||'');break;case 'asset':html=assetView(id);break;case 'library':html=library();break;case 'settings':html=settings();break;default:html=home();}
 $('#app').innerHTML=html+footer();document.body.dataset.view=view;cleanup.push(StudioUI.mount(view,render));$('#app').classList.remove('full-screen','sim-focused');$('#app').classList.add('slide-in');setTimeout(()=>$('#app')?.classList.remove('slide-in'),350);const nav={home:'home',learn:'learn',module:'learn',lesson:'learn',build:'build',project:'build',sandbox:'sandbox',code:'code',atlas:'atlas',asset:'atlas',library:'library',settings:''}[view]||'';$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===nav);if(a.dataset.nav===nav)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=(view==='home'?'Welcome':view==='lesson'?L(id)?.title||'Lesson':view.charAt(0).toUpperCase()+view.slice(1))+' | Kinetic Robotics Studio';mountRobot();hydrateMedia();enrichGlossary();if(view==='sandbox'){currentLab=new Labs.Lab($('#lab-container'),Labs.names[id]?id:'pid',{onChange:(event,v)=>{if(event==='message')dialog('Reason from the model',`<p style="font-size:17px;line-height:1.8">${esc(v)}</p>`);if(event==='note'){S.notes['lab-'+v.key]=v.text;save();toast('Experiment note saved.');}if(event==='export')download(v.name,v.content);}});$('.lab-note').value=S.notes['lab-'+currentLab.type]||'';}
 if(guidedProject&&view==='project'&&id===guidedProject){if(Number(sub||0)<4)autoSlide=setTimeout(()=>{location.hash='/project/'+id+'/'+(Number(sub||0)+1);},15000);else{guidedProject=null;toast('Tour finished. Repeat the steps at your own pace and save real evidence.');}}else guidedProject=null;if(view==='code')initEditor();if(view==='atlas'){const input=$('#asset-search');input.addEventListener('input',()=>{const q=input.value.toLowerCase();$$('.asset-card').forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(q));});}if($('#modal').open)closeDialog();window.scrollTo({top:y,behavior:'instant'});}
