 const answer=e.target.closest('[data-answer]');if(answer){const box=answer.closest('[data-quiz]');if(!box)return;const [id,i]=box.dataset.quiz.split(':'),q=L(id)?.quizzes[Number(i)];if(!q)return;const n=Number(answer.dataset.answer);S.quizzes[id+'-'+i]=n;save();$$('[data-answer]',box).forEach(b=>{b.classList.remove('correct','wrong');if(b===answer)b.classList.add(n===q.correct?'correct':'wrong');});const result=$('.quiz-result',box);result.hidden=false;result.innerHTML=`<strong>${n===q.correct?'Correct.':'Not quite.'}</strong> ${esc(q.explanation)}`;}
